import{_ as l,a0 as d,w as o,s as g,I as a,x as n,a1 as t,A as e,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 中如何使用 gdb 調試 C 程序 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中如何使用 gdb 調試 C 程序 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中如何使用 gdb 調試 C 程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中如何使用 gdb 調試 C 程序 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170116 How to debug C programs in Linux using gdb","title":"在 Linux 中如何使用 gdb 調試 C 程序","tag":"201702","desc":""},"relativePath":"201702/20170116 How to debug C programs in Linux using gdb.md","filePath":"[post].md"}'),r={name:"201702/20170116 How to debug C programs in Linux using gdb.md"};function h(b,s,u,c,k,f){const i=d("Link");return o(),g("div",null,[s[24]||(s[24]=a("h1",{id:"在-linux-中如何使用-gdb-調試-c-程序",tabindex:"-1"},[n("在 Linux 中如何使用 gdb 調試 C 程序 "),a("a",{class:"header-anchor",href:"#在-linux-中如何使用-gdb-調試-c-程序","aria-label":"Permalink to “在 Linux 中如何使用 gdb 調試 C 程序”"},"​")],-1)),s[25]||(s[25]=a("p",null,"無論多麼有經驗的程序員，開發的任何軟件都不可能完全沒有 bug。因此，排查及修復 bug 成為軟件開發週期中最重要的任務之一。有許多辦法可以排查 bug（測試、代碼自審等等），但是還有一些專用軟件（稱為調試器）可以幫助準確定位問題的所在，以便進行修復。",-1)),a("p",null,[s[1]||(s[1]=n("如果你是 C/C++ 程序員，或者使用 Fortran 和 Modula-2 編程語言開發軟件，那麼你將會很樂意知道有這麼一款優秀的調試器 - ",-1)),t(i,{href:"https://www.sourceware.org/gdb/"},{default:e(()=>[...s[0]||(s[0]=[n("GDB",-1)])]),_:1}),s[2]||(s[2]=n(" - 可以幫你更輕鬆地調試代碼 bug 以及其它問題。在這篇文章中，我們將討論一下 GDB 調試器的基礎知識，包括它提供的一些有用的功能/選項。",-1))]),s[26]||(s[26]=a("p",null,"在我們開始之前，值得一提的是，文章中的所有説明和示例都已經在 Ubuntu 14.04 LTS 中測試過。教程中的示例代碼都是 C 語言寫的；使用的 shell 為 bash（4.3.11）；GDB 版本為 7.7.1。",-1)),s[27]||(s[27]=a("h3",{id:"gdb-調試器基礎",tabindex:"-1"},[n("GDB 調試器基礎 "),a("a",{class:"header-anchor",href:"#gdb-調試器基礎","aria-label":"Permalink to “GDB 調試器基礎”"},"​")],-1)),s[28]||(s[28]=a("p",null,"通俗的講，GDB 可以讓你看到程序在執行過程時的內部流程，並幫你明確問題的所在。我們將在下一節通過一個有效的示例來討論 GDB 調試器的用法，但在此之前，我們先來探討一些之後對你有幫助的基本要點。",-1)),s[29]||(s[29]=a("p",null,[n("首先，為了能夠順利使用類似 GDB 這樣的調試器，你必須以指定的方式編譯程序，讓編譯器產生調試器所需的調試信息。例如，在使用 gcc 編譯器（我們將在本教程之後的章節用它來編譯 C 程序示例）編譯代碼的時候，你需要使用 "),a("code",null,"-g"),n(" 命令列選項。")],-1)),a("p",null,[s[4]||(s[4]=n("想要了解 gcc 編譯器手冊頁中關於 ",-1)),s[5]||(s[5]=a("code",null,"-g",-1)),s[6]||(s[6]=n(" 命令列選項相關的內容，請看",-1)),t(i,{href:"https://linux.die.net/man/1/gcc"},{default:e(()=>[...s[3]||(s[3]=[n("這裏",-1)])]),_:1}),s[7]||(s[7]=n("。",-1))]),s[30]||(s[30]=p('<p>下一步，確保在你的系統中已經安裝 GDB 調試器。如果沒有安裝，而且你使用的是基於 Debian 的系統（如 Ubuntu），那麼你就可以使用以下命令輕鬆安裝該工具：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install gdb</span></span></code></pre></div>',2)),a("p",null,[s[9]||(s[9]=n("在其他發行版上的安裝方法，請看",-1)),t(i,{href:"https://www.sourceware.org/gdb/download/"},{default:e(()=>[...s[8]||(s[8]=[n("這裏",-1)])]),_:1}),s[10]||(s[10]=n("。",-1))]),s[31]||(s[31]=p(`<p>現在，當你按照上述的方式編譯完程序（<code>gcc -g</code> 命令列選項），同時也已經安裝好 GDB 調試器，那麼你就可以使用以下命令讓程序在調試模式中運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gdb [可執行程序的名稱]</span></span></code></pre></div><p>這樣做會初始化 GDB 調試器，但你的可執行程序此時還不會被啓動。在這個時候你就可以定義調試相關的設置。例如，你可以在特定行或函數中設置一個斷點讓 GDB 在該行暫停程序的執行。</p><p>接着，為了啓動你的程序，你必須輸入執行以下 gdb 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>run</span></span></code></pre></div><p>在這裏，值得一提的是，如果你的程序需要一些命令列參數，那麼你可以在這裏指定這些參數。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>run [arguments]</span></span></code></pre></div><p>GDB 提供了很多有用的命令，在調試的時候總是能派的上用場。我們將在下一節討論其中一部分命令。</p><h3 id="gdb-調試器用例" tabindex="-1">GDB 調試器用例 <a class="header-anchor" href="#gdb-調試器用例" aria-label="Permalink to “GDB 調試器用例”">​</a></h3><p>現在我們對 GDB 及其用法有了基本的概念。因此，讓我們舉例來應用所學的知識。這是一段示例代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    int out = 0, tot = 0, cnt = 0;</span></span>
<span class="line"><span>    int val[] = {5, 54, 76, 91, 35, 27, 45, 15, 99, 0};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    while(cnt &lt; 10)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        out = val[cnt];</span></span>
<span class="line"><span>        tot = tot + 0xffffffff/out;</span></span>
<span class="line"><span>        cnt++;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    printf(&quot;\\n Total = [%d]\\n&quot;, tot);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>簡單説明一下這段代碼要做什麼事。獲取 <code>val</code> 數組中每一個值，將其賦值給 <code>out</code> 變量，然後將 <code>tot</code> 之前的值與 <code>0xffffffff/out</code> 的結果值累加，賦值給 <code>tot</code> 變量。</p><p>這裏遇到的問題是，當執行這段代碼編譯後的可執行程序時，產生以下錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./gdb-test </span></span>
<span class="line"><span>Floating point exception (core dumped)</span></span></code></pre></div><p>因此，要調試這段代碼，第一步是使用 <code>-g</code> 選項編譯程序。命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gcc -g -Wall gdb-test.c -o gdb-test</span></span></code></pre></div><p>接着，讓我們運行 GDB 調試器並指定要調試的可執行程序。命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gdb ./gdb-test</span></span></code></pre></div><p>現在，我剛才得到的錯誤是 <code>Floating point exception</code>，大部分人可能已經知道，這是因為 <code>n % x</code>，當 x 為 0 時導致的錯誤。所以，考慮到這一點，我在 11 行代碼除法運算的位置處添加了一個斷點。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) break 11</span></span></code></pre></div><p>注意 <code>(gdb)</code> 是調試器的提示信息，我只輸入了 <code>break 11</code> 命令。</p><p>現在，讓 GDB 開始運行程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>run</span></span></code></pre></div><p>當斷點第一次被命中時，GDB 顯示如下輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Breakpoint 1, main () at gdb-test.c:11</span></span>
<span class="line"><span>11 tot = tot + 0xffffffff/out;</span></span>
<span class="line"><span>(gdb)</span></span></code></pre></div><p>正如你所看到的那樣，調試器會顯示斷點所在的行代碼。現在，讓我們打印出此時 <code>out</code> 的值。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) print out</span></span>
<span class="line"><span>$1 = 5</span></span>
<span class="line"><span>(gdb)</span></span></code></pre></div><p>如上所示，值 <code>5</code> 被打印出來了。這個時候一切都還是正常的。讓調試器繼續執行程序直到命中下一個斷點，可以通過使用 <code>c</code> 命令來完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>c</span></span></code></pre></div><p>重複上述操作，直到 <code>out</code> 值變為 <code>0</code> 時。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>...</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Breakpoint 1, main () at gdb-test.c:11</span></span>
<span class="line"><span>11 tot = tot + 0xffffffff/out;</span></span>
<span class="line"><span>(gdb) print out</span></span>
<span class="line"><span>$2 = 99</span></span>
<span class="line"><span>(gdb) c</span></span>
<span class="line"><span>Continuing.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Breakpoint 1, main () at gdb-test.c:11</span></span>
<span class="line"><span>11 tot = tot + 0xffffffff/out;</span></span>
<span class="line"><span>(gdb) print out</span></span>
<span class="line"><span>$3 = 0</span></span>
<span class="line"><span>(gdb)</span></span></code></pre></div><p>現在，為了進一步確認問題，我使用 GDB 的 <code>s</code>（或 <code>step</code>） 命令代替 <code>c</code> 命令。因為，我只想讓當前程序在第 11 行之後暫停，再一步步執行，看看這個時候是否會發生崩潰。</p><p>以下是執行之後輸出信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) s</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Program received signal SIGFPE, Arithmetic exception.</span></span>
<span class="line"><span>0x080484aa in main () at gdb-test.c:11</span></span>
<span class="line"><span>11 tot = tot + 0xffffffff/out;</span></span></code></pre></div><p>是的，如上輸出的第一行內容所示，這就是拋出異常的地方。當我再次嘗試運行 <code>s</code> 命令時，問題最終也得到了確認：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(gdb) s</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Program terminated with signal SIGFPE, Arithmetic exception.</span></span>
<span class="line"><span>The program no longer exists.</span></span></code></pre></div><p>通過這種方式，你就可以使用 GDB 調試你的程序。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>GDB 提供了很多功能供用户研究和使用，在這裏，我們僅僅只介紹了很少一部分內容。通過 GDB 的手冊頁可以進一步瞭解這個工具，當你在調試代碼的時候，嘗試使用一下它。GDB 調試器有一定的學習難度，但是它很值得你下功夫學習。</p><hr>`,40)),a("p",null,[s[12]||(s[12]=n("via: ",-1)),t(i,{href:"https://www.howtoforge.com/tutorial/how-to-debug-c-programs-in-linux-using-gdb/"},{default:e(()=>[...s[11]||(s[11]=[n("https://www.howtoforge.com/tutorial/how-to-debug-c-programs-in-linux-using-gdb/",-1)])]),_:1})]),a("p",null,[s[16]||(s[16]=n("作者：",-1)),t(i,{href:"https://www.howtoforge.com/tutorial/how-to-debug-c-programs-in-linux-using-gdb/"},{default:e(()=>[...s[13]||(s[13]=[n("Ansh",-1)])]),_:1}),s[17]||(s[17]=n(" 譯者：",-1)),t(i,{href:"https://github.com/zhb127"},{default:e(()=>[...s[14]||(s[14]=[n("zhb127",-1)])]),_:1}),s[18]||(s[18]=n(" 校對：",-1)),t(i,{href:"https://github.com/jasminepeng"},{default:e(()=>[...s[15]||(s[15]=[n("jasminepeng",-1)])]),_:1})]),a("p",null,[s[21]||(s[21]=n("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[19]||(s[19]=[n("LCTT",-1)])]),_:1}),s[22]||(s[22]=n(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:e(()=>[...s[20]||(s[20]=[n("Linux中國",-1)])]),_:1}),s[23]||(s[23]=n(" 榮譽推出",-1))])])}const y=l(r,[["render",h]]);export{x as __pageData,y as default};
